**What this code covers**

- Load and parse a JSON config file.
- Process a payment with full error information
- Demonstrates nested try/except and strategic re-raising
- Decorator: retry on exception with exponential backoff
- Catch multiple exceptions in one clause
- Runs ONLY if no exception was raised in try
- Perfect for "success" logic — keeps it separate from try block
- ALWAYS runs — even if an exception was raised

**Defines:** `divide()`, `convert_to_int()`, `parse_data()`, `load_config()`, `load_config_v2()`, `process_payment()`, `fetch_user_data()`, `with_retry()`, `call_external_api()`

**Example 1 — Basic try/except**
```python
# ─── Single exception ───
def divide(a, b):
    try:
        result = a / b
    except ZeroDivisionError:
        print("Error: Cannot divide by zero!")
        return None
    return result

print(divide(10, 2))   # 5.0
print(divide(10, 0))   # Error: Cannot divide by zero! → None

# ─── Multiple except clauses ───
def convert_to_int(value):
    try:
        return int(value)
    except ValueError:
        print(f"'{value}' is not a valid integer string")
        return None
    except TypeError:
        print(f"Cannot convert {type(value).__name__} to int")
        return None

print(convert_to_int("42"))     # 42
print(convert_to_int("hello"))  # 'hello' is not a valid integer string → None
print(convert_to_int([1,2,3]))  # Cannot convert list to int → None
print(convert_to_int(None))     # Cannot convert NoneType to int → None

# ─── Catch multiple exceptions in one clause ───
def parse_data(raw):
    try:
        data = int(raw)
        result = 100 / data
        return result
    except (ValueError, ZeroDivisionError) as e:
        print(f"Data error: {type(e).__name__}: {e}")
        return None

print(parse_data("5"))    # 20.0
print(parse_data("0"))    # Data error: ZeroDivisionError: division by zero
print(parse_data("abc"))  # Data error: ValueError: invalid literal for int()...
```

**Example 2 — else and finally**
```python
import json

def load_config(filepath: str) -> dict:
    """
    Load and parse a JSON config file.
    Demonstrates all four clauses: try/except/else/finally
    """
    file = None
    try:
        file = open(filepath, 'r', encoding='utf-8')
        raw = file.read()
        config = json.loads(raw)

    except FileNotFoundError:
        print(f"❌ Config file not found: {filepath}")
        return {}

    except json.JSONDecodeError as e:
        print(f"❌ Invalid JSON in {filepath}: {e}")
        return {}

    except PermissionError:
        print(f"❌ No permission to read: {filepath}")
        return {}

    else:
        # Runs ONLY if no exception was raised in try
        # Perfect for "success" logic — keeps it separate from try block
        print(f"✅ Config loaded: {len(config)} keys")
        return config

    finally:
        # ALWAYS runs — even if an exception was raised
        # Perfect for cleanup (close files, DB connections, etc.)
        if file:
            file.close()
            print(f"📁 File handle closed")

# ─── Better version using context manager ───
def load_config_v2(filepath: str) -> dict:
    try:
        with open(filepath, 'r', encoding='utf-8') as f:
            config = json.load(f)
    except FileNotFoundError:
        return {}
    except json.JSONDecodeError as e:
        raise ValueError(f"Invalid config file: {e}") from e
    else:
        print(f"✅ Config loaded: {len(config)} settings")
        return config
    # No finally needed — 'with' handles file closing!
```

**Example 3 — Getting Exception Details**
```python
import traceback
import logging

logger = logging.getLogger(__name__)

def process_payment(amount: float, card_number: str) -> dict:
    """Process a payment with full error information"""
    try:
        # Simulate payment processing
        if amount <= 0:
            raise ValueError(f"Amount must be positive, got {amount}")
        if len(card_number) != 16:
            raise ValueError(f"Card number must be 16 digits, got {len(card_number)}")
        if card_number.startswith("0000"):
            raise ConnectionError("Payment gateway unreachable")

        return {"status": "success", "amount": amount, "auth_code": "AUTH123"}

    except ValueError as e:
        # 'e' gives access to the exception object
        logger.warning(f"Validation error: {e}")
        return {"status": "failed", "error": str(e), "type": "validation"}

    except ConnectionError as e:
        logger.error(f"Gateway error: {e}")
        return {"status": "failed", "error": "Payment gateway down", "type": "gateway"}

    except Exception as e:
        # Catch-all for unexpected errors — log full traceback
        logger.critical(
            f"Unexpected error processing payment: {e}\n"
            f"{traceback.format_exc()}"  # Full stack trace as string
        )
        return {"status": "failed", "error": "Internal error", "type": "unknown"}

# ─── Accessing exception attributes ───
try:
    raise ValueError("Something went wrong") from KeyError("root cause")
except ValueError as e:
    print(f"Exception: {e}")
    print(f"Type: {type(e).__name__}")
    print(f"Args: {e.args}")
    print(f"Cause: {e.__cause__}")      # The 'from' exception
    print(f"Context: {e.__context__}")  # Exception raised while handling another
```

**Example 4 — Nested try/except and Re-raising**
```python
def fetch_user_data(user_id: int) -> dict:
    """
    Demonstrates nested try/except and strategic re-raising
    """
    try:
        # ─── Outer try: overall operation ───
        print(f"Fetching user {user_id}...")

        try:
            # ─── Inner try: specific risky operation ───
            if user_id <= 0:
                raise ValueError(f"Invalid user_id: {user_id}")
            # Simulate DB query
            user = {"id": user_id, "name": "Alice"}

        except ValueError as e:
            # Handle specific inner error
            print(f"  Validation failed: {e}")
            raise  # Re-raise the SAME exception to outer handler

        # ─── Another inner try ───
        try:
            score = 100 / (user_id - 5)  # Will fail for user_id=5
        except ZeroDivisionError:
            print("  Score calculation failed — using default")
            score = 0

        user["score"] = score
        return user

    except ValueError as e:
        # Outer handler for ValueError (re-raised from inner)
        print(f"User fetch aborted: {e}")
        return {}

    except Exception as e:
        # Unexpected errors — convert to domain error
        raise RuntimeError(f"Failed to fetch user {user_id}") from e

print(fetch_user_data(1))   # Success
print(fetch_user_data(5))   # ZeroDivisionError handled, score=0
print(fetch_user_data(-1))  # ValueError: Invalid user_id
```

**Example 5 — Production Exception Handling Pattern**
```python
import time
import logging
from typing import Optional, TypeVar, Callable, Any
from functools import wraps

logger = logging.getLogger(__name__)
T = TypeVar('T')

def with_retry(
    max_attempts: int = 3,
    delay: float = 1.0,
    exceptions: tuple = (Exception,)
):
    """Decorator: retry on exception with exponential backoff"""
    def decorator(func: Callable) -> Callable:
        @wraps(func)
        def wrapper(*args, **kwargs):
            last_exception = None

            for attempt in range(1, max_attempts + 1):
                try:
                    result = func(*args, **kwargs)

                except exceptions as e:
                    last_exception = e
                    wait = delay * (2 ** (attempt - 1))

                    if attempt < max_attempts:
                        logger.warning(
                            f"{func.__name__} attempt {attempt}/{max_attempts} "
                            f"failed: {e}. Retrying in {wait:.1f}s..."
                        )
                        time.sleep(wait)
                    else:
                        logger.error(
                            f"{func.__name__} failed after {max_attempts} attempts"
                        )

                else:
                    # Only runs if no exception — success!
                    if attempt > 1:
                        logger.info(
                            f"{func.__name__} succeeded on attempt {attempt}"
                        )
                    return result

                finally:
                    # Always runs — useful for metrics/cleanup
                    pass  # Could record attempt count here

            raise last_exception  # Re-raise last exception after all retries

        return wrapper
    return decorator

@with_retry(max_attempts=3, delay=0.1, exceptions=(ConnectionError, TimeoutError))
def call_external_api(endpoint: str) -> dict:
    """Simulates an unreliable external API"""
    import random
    if random.random() < 0.6:  # 60% failure rate
        raise ConnectionError(f"Connection refused: {endpoint}")
    return {"data": "success", "endpoint": endpoint}

try:
    result = call_external_api("/api/users")
    print(f"Result: {result}")
except ConnectionError as e:
    print(f"All retries exhausted: {e}")
```
